<script setup>
import { computed,onMounted,ref } from 'vue'
import { api } from './api'
const broadcasts=ref([]),bots=ref([]),audience=ref([]),selected=ref(null),loading=ref(false),saving=ref(false),error=ref(''),success=ref('')
const form=ref({name:'',channel_account_id:'',message_text:'',audience_type:'all',contact_ids:[],scheduled_at:''})
const recipientCount=computed(()=>form.value.audience_type==='all'?audience.value.length:form.value.contact_ids.length)
const activeBots=computed(()=>(bots.value||[]).filter(b=>b.active))
function fmt(v){return v?new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—'}
async function load(){loading.value=true;error.value='';try{[bots.value]=await Promise.all([api.telegramBots()]);if(!form.value.channel_account_id&&activeBots.value.length)form.value.channel_account_id=activeBots.value[0].id;await Promise.all([loadHistory(),loadAudience()])}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadHistory(){broadcasts.value=form.value.channel_account_id?await api.broadcasts('telegram',Number(form.value.channel_account_id)):[]}
async function loadAudience(){audience.value=[];form.value.contact_ids=[];if(!form.value.channel_account_id)return;try{audience.value=await api.broadcastTelegramAudience(Number(form.value.channel_account_id))}catch(e){error.value=e.message}}
function toggleAll(){form.value.contact_ids=form.value.contact_ids.length===audience.value.length?[]:audience.value.map(x=>x.id)}
async function createBroadcast(){if(saving.value)return;saving.value=true;error.value='';success.value='';try{const payload={...form.value,channel:'telegram',channel_account_id:Number(form.value.channel_account_id),scheduled_at:form.value.scheduled_at?new Date(form.value.scheduled_at).toISOString():null};const created=await api.createBroadcast(payload);selected.value=await api.broadcast(created.id);broadcasts.value=await api.broadcasts('telegram',Number(form.value.channel_account_id));success.value='Draft created with '+created.total_recipients+' recipient'+(created.total_recipients===1?'':'s')+'.'}catch(e){error.value=e.message}finally{saving.value=false}}
async function openBroadcast(row){error.value='';try{selected.value=await api.broadcast(row.id)}catch(e){error.value=e.message}}
async function queue(){if(!selected.value)return;error.value='';try{selected.value=await api.queueBroadcast(selected.value.id);broadcasts.value=await api.broadcasts('telegram',Number(form.value.channel_account_id));success.value=selected.value.status==='scheduled'?'Broadcast scheduled.':'Broadcast queued for delivery.'}catch(e){error.value=e.message}}
async function cancel(){if(!selected.value)return;error.value='';try{selected.value=await api.cancelBroadcast(selected.value.id);broadcasts.value=await api.broadcasts('telegram',Number(form.value.channel_account_id));success.value='Broadcast cancelled.'}catch(e){error.value=e.message}}
async function sendTest(r){error.value='';success.value='';try{await api.testBroadcast(selected.value.id,r.contact_id);success.value='Test message sent to '+(r.display_name||r.destination)+'.'}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template>
<section class="broadcast-page">
<header class="broadcast-head"><div><p class="eyebrow">Messaging</p><h1>Broadcasts</h1><p>Send a Telegram message to an audience of existing subscribers.</p></div><button class="secondary" @click="load">↻ Refresh</button></header>
<p v-if="error" class="broadcast-error">{{error}}</p><p v-if="success" class="broadcast-success">{{success}}</p>
<div class="broadcast-grid">
<form class="broadcast-card composer-card" @submit.prevent="createBroadcast"><h2>Create broadcast</h2>
<label>Name<input v-model="form.name" maxlength="150" required placeholder="September promotion"/></label>
<label>Channel<select disabled><option>Telegram</option></select></label>
<label>Telegram bot<select v-model="form.channel_account_id" required @change="loadHistory();loadAudience()"><option disabled value="">Select bot…</option><option v-for="b in activeBots" :key="b.id" :value="b.id">{{b.first_name||b.username||('Bot '+b.id)}}{{b.username?' (@'+b.username+')':''}}</option></select></label>
<label>Audience<select v-model="form.audience_type"><option value="all">All subscribers</option><option value="selected">Selected subscribers</option></select></label>
<div v-if="form.audience_type==='selected'" class="audience-box"><div class="audience-tools"><strong>{{form.contact_ids.length}} selected</strong><button type="button" class="link-btn" @click="toggleAll">{{form.contact_ids.length===audience.length?'Clear all':'Select all'}}</button></div><label v-for="c in audience" :key="c.id" class="recipient-check"><input v-model="form.contact_ids" type="checkbox" :value="c.id"/><span>{{c.name}}<small v-if="c.username">@{{c.username}}</small></span></label></div>
<label>Message<textarea v-model="form.message_text" maxlength="4096" rows="8" required placeholder="Hi %first_name%, ..."></textarea><small>Variables: %name%, %first_name%, %last_name%, %username%, %subscriber_id% and custom-field keys.</small></label>
<label>Schedule (optional)<input v-model="form.scheduled_at" type="datetime-local"/></label>
<div class="broadcast-summary"><strong>{{recipientCount}}</strong> recipient{{recipientCount===1?'':'s'}}</div>
<button class="primary" :disabled="saving||!recipientCount">{{saving?'Creating…':'Create draft'}}</button></form>
<section class="broadcast-card list-card"><h2>Broadcast history</h2><div v-if="loading">Loading…</div><div v-else-if="!broadcasts.length" class="empty">No broadcasts yet.</div><button v-for="b in broadcasts" :key="b.id" type="button" class="broadcast-row" :class="{active:selected?.id===b.id}" @click="openBroadcast(b)"><span><strong>{{b.name}}</strong><small>{{fmt(b.created_at)}} · Telegram</small></span><span><b class="status">{{b.status}}</b><small>{{b.sent_count}} / {{b.total_recipients}} sent</small></span></button></section>
<section v-if="selected" class="broadcast-card detail-card"><div class="detail-title"><div><p class="eyebrow">Broadcast #{{selected.id}}</p><h2>{{selected.name}}</h2></div><b class="status">{{selected.status}}</b></div>
<div class="metrics"><div><strong>{{selected.total_recipients}}</strong><span>Recipients</span></div><div><strong>{{selected.sent_count}}</strong><span>Sent</span></div><div><strong>{{selected.failed_count}}</strong><span>Failed</span></div></div>
<pre class="message-preview">{{selected.message_text}}</pre><p v-if="selected.scheduled_at"><strong>Scheduled:</strong> {{fmt(selected.scheduled_at)}}</p>
<div class="actions"><button v-if="['draft','scheduled'].includes(selected.status)" class="primary" @click="queue">{{selected.scheduled_at?'Schedule':'Send broadcast'}}</button><button v-if="!['completed','cancelled'].includes(selected.status)" class="secondary" @click="cancel">Cancel</button></div>
<div class="recipient-list"><h3>Recipients</h3><article v-for="r in selected.recipients" :key="r.id"><span><strong>{{r.display_name||r.destination}}</strong><small>{{r.destination}}</small></span><span><b class="status">{{r.status}}</b><button v-if="selected.status==='draft'" class="link-btn" @click="sendTest(r)">Send test</button></span><p v-if="r.last_error">{{r.last_error}}</p></article></div></section>
</div></section>
</template>
<style scoped>
.broadcast-page{padding:28px;max-width:1500px;margin:0 auto;width:100%}.broadcast-head,.detail-title,.audience-tools{display:flex;justify-content:space-between;align-items:center;gap:16px}.broadcast-head h1,.broadcast-card h2{margin:.2rem 0}.broadcast-head p{margin:.25rem 0;color:#667085}.broadcast-grid{display:grid;grid-template-columns:minmax(320px,440px) minmax(320px,1fr);gap:20px;margin-top:22px;align-items:start}.broadcast-card{background:#fff;border:1px solid #e4e7ec;border-radius:14px;padding:20px;box-shadow:0 1px 2px rgba(16,24,40,.04)}.composer-card{grid-row:span 2;display:grid;gap:14px}.composer-card label{display:grid;gap:6px;font-weight:600}.composer-card input,.composer-card select,.composer-card textarea{width:100%;box-sizing:border-box;border:1px solid #d0d5dd;border-radius:8px;padding:10px 12px;font:inherit}.composer-card small,.broadcast-row small,.recipient-list small{display:block;color:#667085;font-weight:400}.audience-box{border:1px solid #e4e7ec;border-radius:8px;max-height:250px;overflow:auto;padding:10px}.recipient-check{display:flex!important;grid-template-columns:auto 1fr!important;align-items:center;gap:9px!important;padding:6px}.recipient-check input{width:auto}.broadcast-row{width:100%;display:flex;justify-content:space-between;text-align:left;gap:12px;padding:13px;border:0;border-bottom:1px solid #eee;background:transparent;cursor:pointer}.broadcast-row.active{background:#f2f4f7}.broadcast-row>span:last-child{text-align:right}.status{text-transform:capitalize;font-size:12px;background:#f2f4f7;border-radius:999px;padding:4px 8px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.metrics div{background:#f8fafc;border-radius:10px;padding:14px;display:grid}.metrics strong{font-size:24px}.metrics span{color:#667085;font-size:12px}.message-preview{white-space:pre-wrap;font:inherit;background:#f8fafc;padding:14px;border-radius:10px}.actions{display:flex;gap:10px;margin:16px 0}.recipient-list article{display:flex;justify-content:space-between;gap:10px;border-top:1px solid #eee;padding:10px 0}.recipient-list article>span:last-of-type{text-align:right}.recipient-list p{grid-column:1/-1;color:#b42318}.primary,.secondary,.link-btn{border-radius:8px;padding:9px 13px;cursor:pointer}.primary{background:#101828;color:#fff;border:1px solid #101828}.secondary{background:#fff;border:1px solid #d0d5dd}.link-btn{border:0;background:transparent;color:#475467;padding:3px}.broadcast-summary{background:#f8fafc;border-radius:8px;padding:10px}.broadcast-error{color:#b42318}.broadcast-success{color:#067647}@media(max-width:900px){.broadcast-grid{grid-template-columns:1fr}.composer-card{grid-row:auto}}
</style>
